package local.pocketchat;

import org.json.*;
import java.util.*;

/** Production history/report on a host JVM, not an Android or privacy-effectiveness test. */
public final class FingerprintObservationHistoryHost {
  static final String ENV="11111111-1111-4111-8111-111111111111",OTHER="22222222-2222-4222-8222-222222222222";
  static int passed;static JSONArray checks=new JSONArray();
  static void check(String name,boolean value){checks.put(J.obj("name",name,"pass",value));if(!value)throw new AssertionError(name);passed++;}
  static JSONObject copy(JSONObject input){return FingerprintObservationHistory.copy(input);}
  static JSONObject metadata(){return J.obj("environmentId",ENV,"environmentGeneration",1,"configurationRevision",7,"engineVersion","Gecko 157.0.1","appVersion","2.0.24","appVersionCode",77,"sourceOrigin","https://chatgpt.com/c/private-draft?value=not-stored","executionId","first-run");}
  static JSONObject signal(){return J.obj("ua","Firefox/157.0", "language","en-US","languages",new JSONArray(Arrays.asList("en-US","ja-JP")),"offset",-540,"zone","Asia/Tokyo","cpu",8,"memory",JSONObject.NULL,"renderer","restricted","screen",J.obj("width",1080,"height",2400,"availWidth",1080,"availHeight",2300,"depth",24),"viewport",J.obj("width",400,"height",700,"pixelRatio",2.75,"touch",5));}
  static JSONObject api(String hash){return J.obj("schema",1,"probeVersion",1,"requested",true,"source","page-main-world","protectionVerified",false,"limits",J.obj("canvasPixels",4096,"audioFrames",2048,"fontCandidates",5,"totalBudgetMs",1200),"probes",J.obj("canvas",J.obj("state","available","pixels",4096,"hash",hash,"hashAlgorithm","sha256","reason","completed"),"audio",J.obj("state","restricted","reason","NotAllowedError"),"fonts",J.obj("state","failed","reason","Error"),"webgl",J.obj("state","uncovered","reason","unavailable")));}
  static JSONObject sample(){return J.obj("provenance","page-main-world","mainWorld",J.obj("observed",true),"parent",signal(),"frame",signal(),"worker",J.obj("ua","Firefox/157.0","language","en-US","languages",new JSONArray(Arrays.asList("en-US","ja-JP")),"cpu",8,"memory",JSONObject.NULL,"offset",-540,"zone","Asia/Tokyo"));}
  static JSONObject report(long at){return J.obj("fresh",true,"at",at,"signals",sample());}
  static JSONObject comparison(JSONArray history){return history.optJSONObject(history.length()-1).optJSONObject("comparison");}
  static boolean includes(JSONArray values,String text){for(int i=0;i<values.length();i++)if(text.equals(values.optString(i)))return true;return false;}
  static JSONObject row(JSONObject report,String key){JSONArray rows=report.optJSONArray("rows");for(int i=0;i<rows.length();i++)if(key.equals(rows.optJSONObject(i).optString("key")))return rows.optJSONObject(i);throw new AssertionError("Missing "+key);}
  public static void main(String[] args)throws Exception{
    String a=String.join("",Collections.nCopies(64,"a")),b=String.join("",Collections.nCopies(64,"b"));
    JSONArray first=FingerprintObservationHistory.record(new JSONArray(),report(1000),metadata());
    check("First valid main-world observation retained",first.length()==1&&"first-observation".equals(comparison(first).optString("state")));
    check("Real UUID and generation survive",ENV.equals(first.getJSONObject(0).getString("environmentId"))&&first.getJSONObject(0).getInt("environmentGeneration")==1);
    check("Source path and query are not persisted",first.getJSONObject(0).getString("sourceOrigin").equals("https://chatgpt.com")&&!first.toString().contains("private-draft"));
    check("Snapshots contain no viewport width or height",!first.getJSONObject(0).getJSONObject("values").has("viewport")&&!first.toString().contains("availHeight"));
    JSONArray cap=new JSONArray();for(int i=0;i<14;i++)cap=FingerprintObservationHistory.record(cap,report(1000+i),metadata());
    check("Only most recent eight observations retained",cap.length()==8&&cap.getJSONObject(0).getLong("at")==1006&&cap.getJSONObject(7).getLong("at")==1013);
    check("Restore retains bounded valid entries",FingerprintObservationHistory.restore(cap).length()==8);
    JSONObject stale=report(2000);stale.put("fresh",false);check("Stale result does not append",FingerprintObservationHistory.record(first,stale,metadata()).length()==1);
    JSONObject isolated=report(2000);isolated.getJSONObject("signals").put("provenance","extension-isolated-world-fallback");check("Isolated fallback cannot become page history",FingerprintObservationHistory.record(first,isolated,metadata()).length()==1);
    JSONObject absent=report(2000);absent.getJSONObject("signals").put("mainWorld",J.obj("observed",false));check("Missing main-world receipt cannot append",FingerprintObservationHistory.record(first,absent,metadata()).length()==1);
    JSONObject malformed=metadata();malformed.put("environmentId",0);check("Numeric slot cannot replace stable UUID",FingerprintObservationHistory.record(new JSONArray(),report(2000),malformed).length()==0);
    JSONObject noGeneration=metadata();noGeneration.remove("environmentGeneration");check("Unknown environment generation cannot append",FingerprintObservationHistory.record(first,report(2000),noGeneration).length()==1);
    JSONObject other=metadata();other.put("environmentId",OTHER);JSONArray isolatedHistory=FingerprintObservationHistory.record(first,report(2000),other);check("A different environment cannot retain prior environment entries",isolatedHistory.length()==1&&OTHER.equals(isolatedHistory.getJSONObject(0).getString("environmentId")));
    check("Restore owner filter prevents same-slot data crossover",FingerprintObservationHistory.restore(first,OTHER,1).length()==0);
    check("Restore generation filter prevents reset data crossover",FingerprintObservationHistory.restore(first,ENV,2).length()==0);
    JSONObject rotated=report(2000);rotated.getJSONObject("signals").getJSONObject("parent").put("screen",J.obj("width",2400,"height",1080,"availWidth",2200,"availHeight",1080,"depth",24));rotated.getJSONObject("signals").getJSONObject("parent").put("viewport",J.obj("width",700,"height",200,"pixelRatio",2.75,"touch",5));
    JSONArray rotation=FingerprintObservationHistory.record(first,rotated,metadata());check("Rotation and keyboard viewport changes are not fingerprint differences",comparison(rotation).getJSONArray("changedFields").length()==0);
    JSONObject dpr=report(2000);dpr.getJSONObject("signals").getJSONObject("parent").getJSONObject("viewport").put("pixelRatio",3);JSONArray changed=FingerprintObservationHistory.record(first,dpr,metadata());check("An actual DPR observation change is retained",includes(comparison(changed).getJSONArray("changedFields"),"pixelRatio"));
    check("Observed changes never attest a leak",Boolean.FALSE.equals(comparison(changed).opt("leakVerdict"))&&Boolean.FALSE.equals(comparison(changed).opt("protectionVerified")));
    JSONObject restart=metadata();restart.put("executionId","second-run");JSONArray restarted=FingerprintObservationHistory.record(first,report(2000),restart);check("Execution changes label a restart without splitting same template group",comparison(restarted).getBoolean("acrossExecution")&&"comparable".equals(comparison(restarted).getString("state")));
    for(String key:new String[]{"configurationRevision","engineVersion","appVersion","appVersionCode","sourceOrigin"}){
      JSONObject context=metadata();context.put(key,key.equals("configurationRevision")?8:key.equals("appVersionCode")?78:key.equals("sourceOrigin")?"https://identity.example/":"changed-version");JSONObject next=report(2000);next.getJSONObject("signals").getJSONObject("parent").put("ua","Firefox/158.0");JSONArray separate=FingerprintObservationHistory.record(first,next,context);
      check("Different "+key+" is grouped separately",comparison(separate).getString("state").equals("separate-context")&&includes(comparison(separate).getJSONArray("separationReasons"),key));
      check("Different "+key+" retains a clearly diagnostic prior-value comparison",includes(comparison(separate).getJSONArray("diagnosticChangedFields"),"ua")&&comparison(separate).getBoolean("diagnosticOnly"));
    }
    JSONObject sameOrigin=metadata();sameOrigin.put("sourceOrigin","https://CHATGPT.com/another-chat?not=retained");check("Same origin paths remain comparable",comparison(FingerprintObservationHistory.record(first,report(2000),sameOrigin)).getString("state").equals("comparable"));
    JSONObject base=report(3000);base.getJSONObject("signals").put("apiChecks",api(a));JSONArray deep=FingerprintObservationHistory.record(first,base,metadata());
    check("An operation hash is retained without a protection claim",deep.getJSONObject(deep.length()-1).getJSONObject("apis").getJSONObject("canvas").getString("hash").equals(a)&&!deep.getJSONObject(deep.length()-1).getBoolean("protectionVerified"));
    JSONArray restored=FingerprintObservationHistory.restore(deep);check("API hash and algorithm survive process restoration",restored.getJSONObject(restored.length()-1).getJSONObject("apis").getJSONObject("canvas").getString("hash").equals(a));
    JSONObject later=report(5000);later.getJSONObject("signals").put("apiChecks",api(b));JSONArray throughLight=FingerprintObservationHistory.record(deep,report(4000),metadata());JSONArray changedApi=FingerprintObservationHistory.record(throughLight,later,metadata());check("Deep checks compare to last comparable deep sample across a light check",comparison(changedApi).getLong("apiReferenceAt")==3000&&includes(comparison(changedApi).getJSONArray("apiOutputChanges"),"canvas"));
    check("Randomized API output is never treated as leak or native failure",!comparison(changedApi).getBoolean("leakVerdict")&&!comparison(changedApi).getBoolean("protectionVerified"));
    JSONObject versioned=report(6000);JSONObject versionedApi=api(b);versionedApi.put("probeVersion",2);versioned.getJSONObject("signals").put("apiChecks",versionedApi);check("Different probe versions do not compare hashes",comparison(FingerprintObservationHistory.record(deep,versioned,metadata())).getJSONArray("apiOutputChanges").length()==0);
    JSONObject input=report(6000);JSONArray copyHistory=FingerprintObservationHistory.record(first,input,metadata());input.getJSONObject("signals").getJSONObject("parent").getJSONArray("languages").put("later-mutation");check("Recording does not retain mutable input arrays",!copyHistory.toString().contains("later-mutation"));copyHistory.getJSONObject(0).getJSONObject("values").put("ua","mutated-output");check("Returned history does not mutate the original history",!first.toString().contains("mutated-output"));
    JSONObject unsafe=copy(first.getJSONObject(0));unsafe.getJSONObject("values").put("cookie","must-not-retain");unsafe.put("password","must-not-retain");JSONArray sanitized=FingerprintObservationHistory.restore(new JSONArray().put(unsafe));check("Restore whitelists away unrelated stored data",!sanitized.toString().contains("must-not-retain"));
    JSONObject future=copy(first.getJSONObject(0));future.put("schema",2);check("Future history schema is not relabelled as current",FingerprintObservationHistory.restore(new JSONArray().put(future)).length()==0);
    JSONObject stringSchema=copy(first.getJSONObject(0));stringSchema.put("schema","1");check("String schema cannot masquerade as numeric schema",FingerprintObservationHistory.restore(new JSONArray().put(stringSchema)).length()==0);
    check("History detail exposes original observed UA and timezone",FingerprintObservationHistory.summary(changedApi).contains("Firefox/157.0")&&FingerprintObservationHistory.summary(changedApi).contains("Asia/Tokyo"));
    JSONObject expected=J.obj("engine","gecko","ua","Firefox/157.0","major",157,"level",2,"rfpAcknowledged",true,"language","en-US","timezoneStrategy","native-standardized");JSONObject sample=sample();sample.put("apiChecks",api(a));JSONObject apiReport=AuditReport.build(sample,new JSONObject(),expected,false,true);
    check("Canvas success is available operation, not verified protection",row(apiReport,"api-canvas").getString("state").equals("available")&&!apiReport.getBoolean("apiProtectionVerified"));
    check("Restricted audio is distinguished from failure",row(apiReport,"api-audio").getString("state").equals("restricted"));
    check("Failed font operation is distinguished from uncovered",row(apiReport,"api-fonts").getString("state").equals("failed"));
    check("Uncovered WebGL operation remains uncovered",row(apiReport,"api-webgl").getString("state").equals("uncovered"));
    check("Worker missing screen interfaces remains uncovered, not issue",row(apiReport,"display-worker").getString("state").equals("uncovered"));
    check("Original seven-field Worker context still verifies independently",row(apiReport,"worker").getString("state").equals("verified")&&apiReport.getJSONObject("contextCoverage").getJSONArray("requiredFields").length()==7);
    check("Same-origin display fields are compared separately",row(apiReport,"display-frame").getString("state").equals("verified"));
    JSONObject forged=sample();forged.put("apiChecks",api(a));forged.getJSONObject("apiChecks").put("protectionVerified",true);check("A forged all-API protection claim cannot pass operations coverage",row(AuditReport.build(forged,new JSONObject(),expected,false,true),"api-canvas").getString("state").equals("uncovered"));
    JSONObject staleApi=AuditReport.build(sample,new JSONObject(),expected,false,false);check("Stale API operations are uncovered in rows and structured coverage",row(staleApi,"api-canvas").getString("state").equals("uncovered")&&staleApi.getJSONObject("apiOperationCoverage").getJSONObject("probes").getJSONObject("canvas").getString("state").equals("uncovered"));
    JSONObject fallback=sample();fallback.put("apiChecks",api(a));fallback.put("provenance","extension-isolated-world-fallback");fallback.put("mainWorld",J.obj("observed",false));check("Isolated-world API values cannot verify main-page APIs",row(AuditReport.build(fallback,new JSONObject(),expected,false,true),"api-canvas").getString("state").equals("uncovered"));
    JSONObject invalidSchema=sample();invalidSchema.put("apiChecks",api(a));invalidSchema.getJSONObject("apiChecks").put("schema","1");check("String API schema is not numeric schema",row(AuditReport.build(invalidSchema,new JSONObject(),expected,false,true),"api-canvas").getString("state").equals("uncovered"));
    JSONObject fractionalProbe=sample();fractionalProbe.put("apiChecks",api(a));fractionalProbe.getJSONObject("apiChecks").put("probeVersion",1.5);check("Fractional probe version cannot be coerced into current version",row(AuditReport.build(fractionalProbe,new JSONObject(),expected,false,true),"api-canvas").getString("state").equals("uncovered"));
    JSONObject missingPixels=sample();missingPixels.put("apiChecks",api(a));missingPixels.getJSONObject("apiChecks").getJSONObject("probes").getJSONObject("canvas").remove("pixels");check("Available label without operation evidence is not accepted",row(AuditReport.build(missingPixels,new JSONObject(),expected,false,true),"api-canvas").getString("state").equals("uncovered"));
    JSONObject invalidLanguages=report(6000);invalidLanguages.getJSONObject("signals").getJSONObject("parent").put("languages",new JSONArray().put("en-US").put(JSONObject.NULL));JSONArray languageHistory=FingerprintObservationHistory.record(first,invalidLanguages,metadata());check("Partially malformed language list stays missing, not sanitized into comparable",!languageHistory.getJSONObject(languageHistory.length()-1).getJSONObject("values").has("languages")&&includes(comparison(languageHistory).getJSONArray("uncomparedFields"),"languages"));
    JSONObject noCode=metadata();noCode.remove("appVersionCode");JSONArray unknownCode=FingerprintObservationHistory.record(new JSONArray(),report(6000),noCode);unknownCode=FingerprintObservationHistory.record(unknownCode,report(7000),noCode);check("Unknown application code does not create a complete comparison group",comparison(unknownCode).getString("state").equals("separate-context"));
    JSONObject glSample=sample();glSample.put("apiChecks",api(a));JSONObject gl=J.obj("state","available","version","WebGL 1.0","shadingLanguageVersion","GLSL 1.0","vendor","Mozilla","renderer","WebGL","maxTextureSize",4096,"maxRenderbufferSize",4096,"maxVertexAttribs",16,"extensionCount",1,"extensions",new JSONArray().put("WEBGL_lose_context"));glSample.getJSONObject("apiChecks").getJSONObject("probes").put("webgl",gl);check("Typed WebGL capability observation can be available",row(AuditReport.build(glSample,new JSONObject(),expected,false,true),"api-webgl").getString("state").equals("available"));
    gl.put("extensionCount",0.5);check("Fractional WebGL extension count stays uncovered",row(AuditReport.build(glSample,new JSONObject(),expected,false,true),"api-webgl").getString("state").equals("uncovered"));gl.put("extensionCount",1);gl.put("extensions",new JSONArray().put(5));check("Non-string WebGL extension item stays uncovered",row(AuditReport.build(glSample,new JSONObject(),expected,false,true),"api-webgl").getString("state").equals("uncovered"));
    check("Stale structured display coverage is uncovered independently of rows",staleApi.getJSONObject("contextCoverage").getJSONObject("display").getJSONObject("frame").getString("state").equals("uncovered")&&staleApi.getJSONObject("contextCoverage").getJSONObject("display").getJSONObject("frame").getBoolean("invalidated"));
    check("Light check keeps API operations unrequested and uncovered",!AuditReport.build(sample(),new JSONObject(),expected,false,true).getJSONObject("apiOperationCoverage").getBoolean("requested"));
    System.out.println(J.obj("status","passed","passed",passed,"total",passed,"checks",checks,"actualAndroidExecution",false,"scope","Real production pure-Java history and AuditReport; controlled observations only, no Android/Gecko/native fingerprint attestation").toString());
  }
}
